ALTER TABLE conversations ADD COLUMN state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed'));
ALTER TABLE conversations ADD COLUMN assigned_to BIGINT;
ALTER TABLE conversations ADD CONSTRAINT conversations_assignee FOREIGN KEY(assigned_to,tenant_id) REFERENCES users(id,tenant_id);
ALTER TABLE conversations ADD COLUMN bot_paused BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE conversations ADD COLUMN version INT NOT NULL DEFAULT 1;
ALTER TABLE conversations ADD COLUMN labels TEXT[] NOT NULL DEFAULT '{}';
CREATE TABLE conversation_notes(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL,conversation_id BIGINT NOT NULL,user_id BIGINT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(conversation_id,tenant_id) REFERENCES conversations(id,tenant_id),FOREIGN KEY(user_id,tenant_id) REFERENCES users(id,tenant_id));
CREATE TABLE products(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id),sku TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',price_paise BIGINT NOT NULL CHECK(price_paise>=0),stock INT NOT NULL CHECK(stock>=0),reserved INT NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),active BOOLEAN NOT NULL DEFAULT true,version INT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,sku),UNIQUE(id,tenant_id));
CREATE TABLE commerce_orders(id UUID PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id),customer_phone TEXT NOT NULL,customer_name TEXT NOT NULL,address JSONB NOT NULL,items JSONB NOT NULL,total_paise BIGINT NOT NULL CHECK(total_paise>0),payment_method TEXT NOT NULL CHECK(payment_method IN ('cod','online')),payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid','refund_required','refunded')),status TEXT NOT NULL DEFAULT 'confirmed' CHECK(status IN ('awaiting_payment','confirmed','packing','shipped','delivered','cancelled','expired')),expires_at TIMESTAMPTZ,reference TEXT NOT NULL,request_hash TEXT NOT NULL,created_by BIGINT NOT NULL,version INT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,reference),UNIQUE(id,tenant_id),FOREIGN KEY(created_by,tenant_id) REFERENCES users(id,tenant_id));
CREATE TABLE order_events(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL,order_id UUID NOT NULL,action TEXT NOT NULL,user_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(order_id,tenant_id) REFERENCES commerce_orders(id,tenant_id));
CREATE TABLE commerce_payments(id TEXT PRIMARY KEY,tenant_id BIGINT NOT NULL,order_id UUID NOT NULL,amount BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'created',provider_event TEXT UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(order_id,tenant_id) REFERENCES commerce_orders(id,tenant_id));
CREATE TABLE automation_flows(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,trigger_kind TEXT NOT NULL CHECK(trigger_kind IN ('keyword','any')),keyword TEXT NOT NULL DEFAULT '',reply TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT false,published_version INT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(created_by,tenant_id) REFERENCES users(id,tenant_id));
CREATE TABLE automation_versions(flow_id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,version INT NOT NULL,definition JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(flow_id,version),FOREIGN KEY(flow_id,tenant_id) REFERENCES automation_flows(id,tenant_id));
CREATE TABLE automation_runs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL,flow_id BIGINT NOT NULL,flow_version INT NOT NULL,incoming_id BIGINT NOT NULL REFERENCES chat_messages(id),conversation_id BIGINT NOT NULL,reply TEXT NOT NULL,billing_user_id BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','skipped')),error TEXT,lease_until TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(flow_id,incoming_id),FOREIGN KEY(flow_id,tenant_id) REFERENCES automation_flows(id,tenant_id),FOREIGN KEY(conversation_id,tenant_id) REFERENCES conversations(id,tenant_id),FOREIGN KEY(billing_user_id,tenant_id) REFERENCES users(id,tenant_id));
CREATE INDEX automation_run_queue ON automation_runs(status,created_at);
ALTER TABLE automation_runs ADD COLUMN outbound_id BIGINT REFERENCES chat_messages(id);
ALTER TABLE automation_runs ADD COLUMN attempts INT NOT NULL DEFAULT 0;
CREATE TABLE contact_consent(tenant_id BIGINT NOT NULL REFERENCES tenants(id),phone TEXT NOT NULL,opted_out BOOLEAN NOT NULL DEFAULT false,source TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,phone));
